def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        if len(protocol_version) != 2:
            raise ValueError("protocol_version must be a 2-tuple")
    protocol_handlers = {}
    for protocol_version, handler_class in cls.SUPPORTED_PROTOCOL_HANDLERS.items():
        if protocol_version[0] > protocol_version[1]:
            raise ValueError("protocol_version must be a 2-tuple with first element less than or equal to second element")
        if protocol_version[1] < 1:
            raise ValueError("protocol_version must be a 2-tuple with second element greater than or equal to 1")
        if protocol_version[1] > 10:
            raise ValueError("protocol_version must be a 2-tuple with second element less than or equal to 10")
        if protocol_version == (0, 0):
            continue
        if protocol_version[0] == protocol_version[1]:
            if protocol_version[0] == 10:
                continue
            protocol_handlers[protocol_version] = handler_class
        else:
            if protocol_version[0] == 10 and protocol_version[1] == 9:
                protocol_handlers[(9, 8)] = handler_class
            if protocol_version[0] == 9 and protocol_version[1] == 8:
                protocol_handlers[(8, 7)] = handler_class
            if protocol_version[0] == 8 and protocol_version[1] == 7:
                protocol_handlers[(7, 6)] = handler_class
            if protocol_version[0] == 7 and protocol_version[1] == 6:
                protocol_handlers[(6, 5)] = handler_class
            if protocol_version[0] == 6 and protocol_version[1] == 5:
                protocol_handlers[(5, 4)] = handler_class
            if protocol_version[0] == 5 and protocol_version[1] == 4:
                protocol_handlers[(4, 3)] = handler_class
            if protocol_version[0] == 4 and protocol_version[1] == 3:
                protocol_handlers[(3, 2)] = handler_class
            if protocol_version[0] == 3 and protocol_version[1] == 2:
                protocol_handlers[(2, 1)] = handler_class
            if protocol_version[0] == 2 and protocol_version[1] == 1:
                protocol_handlers[(1, 0)] = handler_class
    if protocol_version is not None:
        protocol_handlers = {k: v for k, v in protocol_handlers.items() if k == protocol_version}
    return protocol_handlers

