def pop_u16(self):
    # Check if self is a valid stream
    if not hasattr(self, 'read'):
        raise TypeError('Expected a valid stream object')

    # Ensure there are at least 2 bytes available for reading
    if self.remaining_data() < 2:
        raise UnexpectedEOFError('Attempted to read U16, but only %d bytes available' % self.remaining_data())

    # Read the last two bytes as a big-endian 16-bit unsigned integer
    return self.unpack('>H', 2)

