    """ Dynamically create a Point subclass.
    """
    class Point(type):
        __slots__ = ()

        def __init__(self, x=None, y=None, z=None):
            super().__init__()
            for field, value in zip(fields, srid_map.keys()):
                setattr(self, field, value)

        def __str__(self):
            return '{} : {}'.format(self.__class__.__name__,
                                    ', '.join(['{}={}'.format(field, getattr(self, field)) for field in fields]))

        def __repr__(self):
            return self.__str__()

        def __eq__(self, other):
            if not isinstance(other, Point):
                return False
            for field in fields:
                if getattr(self, field) != getattr(other, field):
                    return False
            return True

    return Point
