def lfu_cache(func=None, maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if func is None:
        return lambda f: lfu_cache(f, maxsize, typed)

    cache = dict()
    hits = dict()

    @functools.wraps(func)
    def decorated_function(*args, **kwargs):
        cache_key = cache_key_from_args(args, kwargs, typed)
        if cache_key in cache:
            cache[cache_key]['freq'] += 1
            hits[cache_key] += 1
            return cache[cache_key]['value']

        result = func(*args, **kwargs)
        cache_value = {
            'value': result,
            'freq': 1
        }
        cache[cache_key] = cache_value
        if len(cache) > maxsize:
            # Least Frequently Used (LFU) cache eviction strategy
            evicted_key = min(hits.items(), key=operator.itemgetter(1))[0]
            cache.pop(evicted_key)

        return result

    return decorated_function


