def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    if len(classes) == 1:
        return [classes[0]]
    result = []
    for c in classes:
        if c not in result:
            for b in get_bases(c):
                if b not in result:
                    result.append(b)
        for b in reversed(result):
            if b in get_bases(c):
                result.remove(b)
        result.append(c)
    return result
