def difference(d1, d2, level=-1):
    if level == 0 or d1 is None or d2 is None:
        return {}
    if d1 is None or d2 is None:
        return d1 if d2 is None else d2
    if isinstance(d1, dict):
        result = {}
        for key, value in d1.items():
            if key not in d2:
                result[key] = value
            elif level > 1 and not isinstance(d2[key], dict):
                result[key] = value
            else:
                result[key] = difference(value, d2[key], level-1)
        return result
