def convert_dict_to_out_style(sql, params):
    # Replace named parameters with placeholders
    sql = sql.replace(':', '%s')
    # Format parameters into a list of tuples
    params = [(key, params[key]) for key in params]
    return sql % params

def convert_sequence_to_out_style(sql, params):
    # Replace ordinal parameters with placeholders
    param_count = len(params)
    for i in range(param_count):
        param = '${}'.format(i + 1)
        sql = sql.replace(param, '%s')
    return sql % tuple(params)
