def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    :param prior: The prior InventoryValidator object.
    :return: True if prior is a valid prior version of the current inventory, False otherwise.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")

    if (self.created_at < prior.created_at) or (prior.created_at >= self.deleted_at):
        return False

    if not prior.check_version_numbers(self.version_number):
        return False

    # Check inventory items
    for item in self.items:
        if item not in prior.items:
            return False

    # Check inventory levels
    for item in self.items:
        if self.levels[item] != prior.levels[item]:
            return False

    # Check inventory prices
    for item in self.items:
        if self.prices[item] != prior.prices[item]:
            return False

    return True
