    # Check that each hash is of the correct length
    length = len(fixity['algorithm'])
    for i, hash_value in enumerate(hashes):
        if len(hash_value) != length:
            raise ValueError(f"Invalid hash value at index {i}: {hash_value}")

    # Check that all files are in the manifest
    for hash_value in hashes:
        if hash_value not in manifest_files:
            raise ValueError(f"File with hash {hash_value} not found in manifest")
