        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise TypeError("Fixity must be a dictionary.")
        if not isinstance(manifest_files, list):
            raise TypeError("Manifest files must be a list.")
        for file_id in manifest_files:
            if file_id not in fixity:
                raise ValueError("File not listed in fixity: %s" % file_id)
        for file_id, checksum in fixity.items():
            if not isinstance(checksum, str):
                raise TypeError("Checksum must be a string.")
