def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s).

    :param commands: commands to be called
    :type commands: list of str
    :param args: arguments to be passed to the commands
    :type args: list of str
    :param cwd: working directory
    :type cwd: str
    :param verbose: Whether to output the output
    :type verbose: bool
    :param hide_stderr: Whether to hide stderr. In case the commands fail, this function can raise a RuntimeError
    :type hide_stderr: bool
    :param env: Environment variables to be passed to the commands
    :type env: dict
    """
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]

    result = ''
    outputs = {}
    for command in commands:
        output = run_single_command(command, args, cwd, verbose, hide_stderr, env)
        result += output.stdout
        outputs[command] = output

    if verbose:
        print(result)

    return result, outputs

def run_single_command(command, args, cwd, verbose, hide_stderr, env):
    """Call a single command."""
    if not command or not isinstance(command, str):
        raise ValueError("Command must be specified and must be a string")
    if args and not isinstance(args, list):
        raise ValueError("Args must be a list of strings")

    if verbose:
        if cwd:
            print(cwd)
        print(command + " " + " ".join(args))

    try:
        result = subprocess.run([command, *args], cwd=cwd, stdout=subprocess.PIPE, stderr=(subprocess.PIPE if not hide_stderr else subprocess.DEVNULL), env=env)
        if verbose and result.stderr:
            print(result.stderr)
    except Exception as e:
        if isinstance(e, FileNotFoundError):
            raise e
        else:
            error = ""
            if cwd:
                error += "cwd: {}\n".format(cwd)
            error += "command: {}\n".format(command)
            if args:
                error += "args: {}\n".format(" ".join(args))
            raise RuntimeError(error) from e

    return result
