    for argument in unparsed_arguments:
        if argument in subparsers:
            parser = subparsers[argument]
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_args[argument] = namespace
            remaining_args = remaining
        else:
            remaining_args = unparsed_arguments
