def parse_subparser_arguments(unparsed_arguments, subparsers):
    subparsers_ns = {}
    args_left = []
    for subparser_name, subparser in subparsers.items():
        subparser_ns = subparser.parse_known_args(unparsed_arguments)
        if subparser_ns:
            subparsers_ns[subparser_name] = subparser_ns[0]
            args_left = subparser_ns[1]
            break
    return subparsers_ns, args_left
