def deep_merge_nodes(nodes):
    # Initialize a dictionary to store unique nodes
    unique_nodes = {}

    # Iterate through each node in the list
    for node in nodes:
        # Get the key of the node (i.e., its label)
        key = node[0]

        # If the key already exists in the unique nodes dictionary,
        # merge the values of the current node with the existing value
        if key in unique_nodes:
            unique_nodes[key] = _deep_merge_dicts(unique_nodes[key], node[1])
        # Otherwise, add the node to the unique nodes dictionary
        else:
            unique_nodes[key] = node[1]

    # Convert the dictionary back into a list of tuples and return it
    return list(unique_nodes.items())

# Helper function to deep merge two dictionaries
def _deep_merge_dicts(dict1, dict2):
    # Initialize a dictionary to store the merged values
    merged_dict = {}

    # Iterate through each key in both dictionaries
    for key in set(dict1.keys()).union(dict2.keys()):
        # If the key exists in both dictionaries and the values are dictionaries,
        # recursively merge the values
        if key in dict1 and key in dict2 and isinstance(dict1[key], dict) and isinstance(dict2[key], dict):
            merged_dict[key] = _deep_merge_dicts(dict1[key], dict2[key])
        # Otherwise, use the value from the second dictionary (dict2)
        else:
            merged_dict[key] = dict2.get(key, dict1.get(key))

    # Return the merged dictionary
    return merged_dict
