def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    import shlex
    from borgmatic.cli import helpers as h
    from borgmatic.decorators import decorator, resolved
    from borgmatic.exception import BorgError
    from borgmatic.params import get_params, get_commands, get_aliases
    from borgmatic.config import BGV_CHAR
    from borgmatic.lib import locate_command_path
    import os
    import sys
    import runpy
    import textwrap

    # helper functions
    def bash_completion_output(command):
        ctx = click.Context(command)
        options = []
        arguments = set()
        for name, param in get_params(command):
            if param.hidden:
                continue
            if param.is_flag:
                options.append(param.opts[0])
            else:
                arguments.add(param.name)
        options.sort()
        arguments.sort()
        return "\n".join(f"{opt}{BGV_CHAR}" for opt in options) + "\n" + "\n".join(arg for arg in arguments)

    def load_command(name):
        try:
            module = sys.modules["borgmatic.commands"]
        except KeyError:
            module = runpy.run_module("borgmatic.commands", run_name="__main__")
        return getattr(module, name)

    # generate script for all valid command parsers
    script = ""
    for name, parser in get_commands():
        try:
            command = load_command(name)
            helper = h.create_ctx_helper(command)
            if callable(getattr(helper, "bash_completion", None)):
                script += textwrap.dedent("""
                    {} && true summary line for {}
                    {comp_out}
                """).format(
                    name,
                    comp_out=bash_completion_output(command).rstrip(),
                    command=name,
                )
        except (BorgError, AttributeError, TypeError, RuntimeError) as exc:
            pass
    return script

