def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    parser = borgmatic.get_default_command_free_arg_parser()
    for subcommand in borgmatic.core.list_subcommands():
        subparser = argparse.ArgumentParser(parents=[parser])
        subcommand(subparser, borgmatic.core.stash)
        args = subparser.parse_args()
        for option in chain(args._get_all_options(), args._get_positional_actions()):
            if option.choices:
                for choice in option.choices:
                    sub = subcommand.replace(':', '_') + '_' + choice
                    sub_completion_script = 'complete -o default -F _minimal -F _commandprefix _borg {}'.format(sub)
                    completions.append(sub_completion_script)
            else:
                # Parse the description to extract the options and their descriptions
                description = option.description.split('\n')
                for line in description:
                    if line.startswith('-'):
                        # Skip options with no descriptions
                        continue
                    option_names = line.split(',')
                    for option_name in option_names:
                        # Format the name and description
                        if option.metavar is not None:
                            option_name = option.metavar.upper()
                        option_name = option_name.replace('-', '_')
                        sub = subcommand.replace(':', '_') + '_' + option_name
                        sub_completion_script = 'complete -o default -F _minimal -F _commandprefix _borg {}'.format(sub)
                        completions.append(sub_completion_script)
    # Return the joined list of completions
    return '\n'.join(completions)
