This code uses the `sizes` list to define the different units of measure, and then iterates over the list to find the corresponding unit of measure in the input string using the `upper()` method to convert the input to uppercase. The resulting value is an approximation as the input value is in most cases rounded.

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    size = size.upper()
    size_num = ''.join(filter(lambda x: x.isdigit(), size))
    size_unit = ''.join(filter(lambda x: x.isalpha(), size))

    if not size_num or not size_unit:
        raise ValueError("Invalid human readable file size format")

    size_num = int(size_num)

    if size_unit == "K":
        size_num *= 1024
    elif size_unit == "M":
        size_num *= 1024 ** 2
    elif size_unit == "G":
        size_num *= 1024 ** 3
    elif size_unit == "T":
        size_num *= 1024 ** 4
    elif size_unit == "P":
        size_num *= 1024 ** 5
    elif size_unit == "E":
        size_num *= 1024 ** 6
    elif size_unit == "Z":
        size_num *= 1024 ** 7
    elif size_unit == "Y":
        size_num *= 1024 ** 8
    else:
        raise ValueError("Invalid human readable file size unit")

    return size_num

