def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:

    if not isinstance(number, int):
        raise ValueError("number must be an integer")

    if not isinstance(alphabet, list) or not all(isinstance(x, str) for x in alphabet):
        raise ValueError("alphabet must be a list of strings")

    if not all(len(x) == 1 for x in alphabet):
        raise ValueError("alphabet must be a list of single characters")

    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    if padding is not None and padding < 0:
        raise ValueError("padding must be a positive integer or None")

    if padding is None:
        padding = 0

    base = len(alphabet)
    digits = []

    while number > 0:
        r = number % base
        digits.append(alphabet[r])
        number //= base

    start_index = 0
    while start_index < len(digits) and digits[start_index] == alphabet[0]:
        start_index += 1

    output = "".join(digits[start_index:])

    if padding > 0:
        output = (padding * alphabet[0])[:padding - len(output)] + output

    return output

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding < 0:
        raise ValueError("padding must be a non-negative integer")

    base = len(alphabet)
    if number < 0:
        negative = True
        number = -number
    else:
        negative = False

    if padding is not None:
        number = number.zfill(padding)

    result = ""

    while number > 0:
        index = number % base
        number = number // base
        result = alphabet[index] + result

    if negative:
        result = alphabet[0] + result

    return result

