def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.

    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(
            f"Specified archive file '{archive_path}' not found."
        )

    temp_repo_dir = tempfile.TemporaryDirectory(dir=tmp_path)
    try:
        subprocess.run(
            ["tar", "-xvf", archive_path, "-C", temp_repo_dir.name], check=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Extracting archive '{archive_path}' failed with error: {e}"
        )

    if filename:
        file_path = pathlib.Path(temp_repo_dir.name) / filename
        if not file_path.is_file():
            raise FileNotFoundError(
                f"Specified file '{filename}' not found in extracted archive '{archive_path}'."
            )
        return f"file://{file_path.resolve()}"
    else:
        return f"file://{temp_repo_dir.name}"

Note: The method raises FileNotFoundError if the specified archive file does not exist, RuntimeError if extracting the archive fails, and FileNotFoundError if the specified file is not found in the extracted archive (if filename is provided).

