def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if len(commands) == 0:
        raise ValueError("No command provided")
    if not isinstance(args, list):
        args = [args]
    if not cwd:
        cwd = os.getcwd()
    if not env:
        env = os.environ
    if verbose:
        print(f"Running command {commands[0]} with argument {' '.join(args)}")
    try:
        subprocess.run(commands, args, cwd=cwd, stderr=subprocess.DEVNULL if hide_stderr else None, env=env)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command {commands[0]} failed with return code {e.returncode}") from e
