def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configurations = {}
    parse_errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, "r") as f:
                config = json.load(f)
        except FileNotFoundError as e:
            parse_errors.append(logging.LogRecord(
                level=logging.ERROR,
                msg=f"Could not find configuration file {config_filename}"
            ))
        except json.JSONDecodeError as e:
            parse_errors.append(logging.LogRecord(
                level=logging.ERROR,
                msg=f"Error parsing configuration file {config_filename}: {e}"
            ))
        else:
            if overrides:
                config = apply_overrides(config, overrides)
            if resolve_env:
                config = resolve_env_vars(config)
            configurations[config_filename] = config

    return configurations, parse_errors

def apply_overrides(config, overrides):
    for override in overrides:
        key, val = override.split("=", maxsplit=1)
        try:
            key, *rest = key.split(".")
            obj = config[key]
            for k in rest:
                obj = obj[k]
            obj.update(val)
        except (KeyError, ValueError) as e:
            pass

    return config

def resolve_env_vars(config):
    for key, val in config.items():
        if isinstance(val, str) and val.startswith("${"):
            var_name = val[2:-1]
            try:
                config[key] = os.environ[var_name]
            except KeyError as e:
                pass

    return config

