def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.
    :param iface: The interface to verify the candidate against.
    :param candidate: The candidate that implements the interface.
    :param tentative: If True, only verify ``iface.providedBy`` (default False).
    :return bool: True if everything that could be checked passed, False otherwise.
    :raises zope.interface.Invalid: If the candidate does not correctly implement the interface.
    """
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate} does not claim to implement {iface}")
    provides_methods = iface.getMethods()
    for method_name, method in provides_methods.items():
        if not hasattr(candidate, method_name):
            raise zope.interface.Invalid(f"{method} is not implemented by {candidate}")
        candidate_method = getattr(candidate, method_name)
        if not callable(candidate_method):
            raise zope.interface.Invalid(f"{candidate_method} is not a method")
        method_signature = inspect.getfullargspec(method)
        candidate_method_signature = inspect.getfullargspec(candidate_method)
        if method_signature != candidate_method_signature:
            raise zope.interface.Invalid(f"Signature of {candidate_method} does not match {method}")
    provides_attrs = iface.getAttributes()
    for attr_name, attr in provides_attrs.items():
        if not hasattr(candidate, attr_name):
            raise zope.interface.Invalid(f"{attr} is not implemented by {candidate}")
        candidate_attr = getattr(candidate, attr_name)
        if attr.readonly:
            if not hasattr(candidate_attr, "class"):
                raise zope.interface.Invalid(f"{candidate_attr} is not read-only")
    return True

