def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    if not isinstance(candidate, typing.Any):
        raise TypeError("candidate must be a any object")

    if not hasattr(iface, "__dict__"):
        raise TypeError("iface must have a __dict__ attribute")

    if not hasattr(candidate, "__dict__"):
        raise TypeError("candidate must have a __dict__ attribute")

    if not isinstance(tentative, bool):
        raise TypeError("tentative must be a boolean")

    iface_attributes = iface.__dict__.keys()
    candidate_attributes = candidate.__dict__.keys()

    if iface_attributes.issubset(candidate_attributes):
        for attr in iface_attributes:
            if not hasattr(candidate, attr):
                raise AttributeError(f"Candidate does not have attribute {attr}")
            if not isinstance(getattr(candidate, attr), getattr(iface, attr)):
                raise ValueError(f"Attribute {attr} does not match expected type")

    else:
        raise AttributeError("Candidate does not provide all mandatory attributes")

    return True

