        raise TypeError('iface must be an Interface')
    if not isinstance(candidate, type):
        raise TypeError('candidate must be a class')
    if not issubclass(candidate, iface):
        raise TypeError('candidate must be a subclass of iface')
    if not hasattr(candidate, '__instancecheck__'):
        raise TypeError('candidate must have a __instancecheck__ method')
    ifaceSpec = iface.get_spec()
    candidateSpec = candidate.get_spec(candidate.__instancecheck__)
    for (attrName, attrSpec) in ifaceSpec.items():
        if attrName not in candidateSpec:
            raise TypeError('candidate is missing %s attribute' % attrName)
        if not candidateSpec[attrName].isCompatibleType(attrSpec):
