def _create_in_regex(self):
    """Create the in-style parameter regular expression."""
    flags = 0
    patterns = []
    for param in self.params:
        if param.location == "QUERY":
            flags |= re.IGNORECASE
        patterns.append(re.escape(param.name))
    return re.compile("(" + "|".join(patterns) + ")", flags=flags)

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    name = self.name
    in_pattern = ""
    for in_param in self.in_params:
        try:
            pattern = self.param_patterns[in_param.name]
            in_pattern += "({})".format(pattern.pattern)
        except KeyError:
            raise ValueError("Parameter {} has no regex pattern defined".format(in_param.name))
    return re.compile(in_pattern)

