def isoparse(dt_str):
    dt_parts = dt_str.split('T')
    date_parts = dt_parts[0].split('-')
    time_parts = None
    if len(dt_parts) > 1 and dt_parts[1].strip():
        time_parts = dt_parts[1].split(':')
    time_micros_parts = None
    if len(time_parts) > 3 and time_parts[3].strip():
        time_micros_parts = time_parts[3].split('.')
    date_separator = '-'
    if len(date_parts) == 3 and date_parts[2].isdigit():
        date_separator = ''
    time_separator = ':'
    if len(time_parts) == 3 and time_parts[2].split():
        time_separator = ''
    time_micros_separator = '.'
    if len(time_micros_parts) == 2 and time_micros_parts[1].strip():
        time_micros_separator = ''

    year = int(date_parts[0])
    month = int(date_parts[1])
    day = int(date_parts[2])

    hour = 0
    minute = 0
    second = 0
    microsecond = 0

    if len(time_parts) == 1 and time_parts[0].isdigit():
        hour = int(time_parts[0])
    elif len(time_parts) == 2 and time_parts[0].isdigit() and time_parts[1].isdigit():
        hour = int(time_parts[0])
        minute = int(time_parts[1])
    elif len(time_parts) == 3 and time_parts[0].isdigit() and time_parts[1].isdigit() and time_parts[2].isdigit():
        hour = int(time_parts[0])
        minute = int(time_parts[1])
        second = int(time_parts[2])
    elif len(time_parts) == 4 and time_parts[0].isdigit() and time_parts[1].isdigit() and time_parts[2].isdigit() and time_parts[3].isdigit():
        hour = int(time_parts[0])
        minute = int(time_parts[1])
        second = int(time_parts[2])
        microsecond = int(time_parts[3].replace('.', ''))
    elif len(time_micros_parts) == 1 and time_micros_parts[0].isdigit():
        hour = int(time_micros_parts[0])

    if time_micros_parts[1].isdigit():
        microsecond = int(time_micros_parts[1].replace('.', ''))

    iso_time = datetime.time(hour, minute, second, microsecond)
    iso_date = datetime.date(year, month, day)

    offset = None
    offset_separator = ''
    if len(time_parts) >= 4 and time_parts[-1].replace('+', '-').replace(':', '').isdigit():
        offset_str = time_parts[-1]
    if offset_str and offset_str.startswith('-'):
        offset_separator = '-'
        offset_str = offset_str[1:]
    elif offset_str and offset_str.startswith('+'):
        offset_separator = '+'
        offset_str = offset_str[1:]
    if offset_str and offset_str.replace(':', '').isdigit():
        offset = datetime.timedelta(hours=int(offset_str[0:2]), minutes=int(offset_str[2:]))
    if offset:
        if offset_separator == '-':
            iso_date = iso_date + offset
        elif offset_separator == '+':
            iso_date = iso_date - offset

    return datetime.datetime.combine(iso_date, iso_time, tzinfo=offset)
