def parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    """
    Parse the date/time string into a datetime.datetime object.

    :param timestr: The date/time string to parse.
    :type timestr: str
    :param default: A default datetime object, elements in timestr replace elements in the default object.
    :type default: datetime.datetime, optional
    :param ignoretz: If set to True, time zones in parsed strings are ignored and a naive datetime.datetime object is returned.
    :type ignoretz: bool, optional
    :param tzinfos: Additional time zone names / aliases which may be present in the string. This parameter maps time zone names and time zone offset to time zones.
    :type tzinfos: dict, optional
    :param \\*\\*kwargs: Additional keyword arguments passed to _parse().
    :type \\*\\*kwargs: dict, optional
    :return: A datetime.datetime object or, if the fuzzy_with_tokens option is True, a tuple, the first element being a datetime.datetime object and the second being a tuple containing the fuzzy tokens.
    :rtype: datetime.datetime
    :raises ParserError: Raised for invalid or unknown string format, if the provided tzinfo is not in a valid format, or if an invalid date would be created.
    :raises TypeError: Raised for non-string or character stream input.
    :raises OverflowError: Raised if the parsed date exceeds the largest valid C integer on your system.
    """
    if not isinstance(timestr, str):
        raise TypeError("timestr must be a string")
    if default is None:
        default = datetime.datetime.utcnow()
    if not isinstance(default, datetime.datetime):
        raise TypeError("default must be a time.struct_time or None")
    if tzinfos is None:
        tzinfos = {}
    if not isinstance(tzinfos, dict):
        raise TypeError("tzinfos must be a dict")
    for name, tz in tzinfos.items():
        if not isinstance(tz, int) and not isinstance(tz, datetime.tzinfo):
            raise TypeError("tzinfos values must be integers or tzinfo objects")
    parsed, tokens = _parse(timestr, ignoretz, tzinfos, **kwargs)
    if not isinstance(parsed, datetime.datetime):
        raise TypeError("parsed must be a time.struct_time")
    if hasattr(parsed, "tzinfo"):
        tzinfo = parsed.tzinfo
    else:
        tzinfo = None
    if ignoretz and tzinfo:
        tzinfo = None
